import { readFile } from "node:fs/promises";

const [, , file, key = "spinnerTipsEnabled"] = process.argv;
if (!file) {
  console.error("usage: node trace-layering.mjs FILE [KEY]");
  process.exit(2);
}

const input = JSON.parse(await readFile(file, "utf8"));
if (!Array.isArray(input.layers)) {
  console.error("ERROR: fixture.layers must be an array");
  process.exit(2);
}

console.log(`KEY ${key}`);
let winner = null;
for (const layer of input.layers) {
  const hasKey = Object.prototype.hasOwnProperty.call(layer.settings ?? {}, key);
  console.log(`${layer.name}: ${hasKey ? JSON.stringify(layer.settings[key]) : "absent"}`);
  if (hasKey) winner = { name: layer.name, value: layer.settings[key] };
}

if (!winner) {
  console.error(`ERROR: no layer defines ${key}`);
  process.exit(1);
}
console.log(`WINNER ${winner.name}`);
console.log(`EFFECTIVE ${JSON.stringify(winner.value)}`);
